BEGIN;
INSERT INTO blog_calendar SELECT * FROM json_populate_record(null::blog_calendar, U&'{"id":"64a6d0e7-e04c-442a-a74f-61aaefb634e8","week_number":22,"scheduled_date":"2026-07-19","title_fr":"Coliving et couple : est-ce que \00E7a marche ?","title_en":"Coliving as a Couple: Does It Work?","category":"coliving","target_audience":"Couples jeunes pros","key_points":["chambres doubles","intimit\00E9","budget couple vs 2 studios","communaut\00E9","espaces communs et priv\00E9s"],"seo_keywords":["coliving couple","logement couple gen\00E8ve","chambre double coliving"],"image_url":"/images/villa_portrait.webp","is_generated":true,"blog_post_id":null,"created_at":"2026-02-16T07:41:06.691494+00:00","updated_at":"2026-07-31T13:47:22.002586+00:00"}'::json);
INSERT INTO blog_calendar SELECT * FROM json_populate_record(null::blog_calendar, U&'{"id":"e99838b4-15a9-496a-a2c0-ec5389a02684","week_number":null,"scheduled_date":"2027-01-15","title_fr":"Coliving et couple : est-ce que \00E7a marche ?","title_en":"Coliving as a couple: does it work?","category":"coliving","target_audience":"Couples de frontaliers/jeunes pros envisageant le coliving","key_points":["R\00E9ponse honn\00EAte : pour quels couples \00E7a marche, pour lesquels non","Politique La Villa (chambres, tarifs couple le cas \00E9ch\00E9ant \2014 v\00E9rifier avec J\00E9r\00F4me avant g\00E9n\00E9ration)","T\00E9moignages et alternatives si non adapt\00E9","Pr\00E9-qualification : \00E9viter les candidatures inadapt\00E9es","CTA candidature"],"seo_keywords":["coliving couple","colocation couple Gen\00E8ve","vivre en coliving \00E0 deux"],"image_url":null,"is_generated":false,"blog_post_id":null,"created_at":"2026-07-31T13:47:22.002586+00:00","updated_at":"2026-07-31T13:47:22.002586+00:00"}'::json);
UPDATE blog_calendar c SET week_number = r.week_number, scheduled_date = r.scheduled_date, title_fr = r.title_fr, title_en = r.title_en, category = r.category, target_audience = r.target_audience, key_points = r.key_points, seo_keywords = r.seo_keywords, image_url = r.image_url, is_generated = r.is_generated, blog_post_id = r.blog_post_id, updated_at = r.updated_at FROM json_populate_record(null::blog_calendar, U&'{"id":"27da94d1-47fb-4f76-a447-60a28173e529","week_number":null,"scheduled_date":"2026-07-31","title_fr":"Rentr\00E9e \00E0 Gen\00E8ve : la checklist logement du frontalier qui arrive en septembre","title_en":"Moving to Geneva in September: the cross-border worker''s housing checklist","category":"tips","target_audience":"Frontaliers et jeunes pros qui prennent un poste \00E0 Gen\00E8ve \00E0 la rentr\00E9e","key_points":["Chronologie invers\00E9e : J-60 \00E0 J-0 avant la prise de poste","Documents \00E0 pr\00E9parer (contrat suisse, permis G en cours = pas bloquant)","Pi\00E8ges de la recherche \00E0 distance (arnaques, visites impossibles)","Option coliving : emm\00E9nagement en 72 h d\00E8s le premier contact si une chambre est disponible, dossier simplifi\00E9","CTA candidature + lien /annemasse-colocation"],"seo_keywords":["s''installer pr\00E8s de Gen\00E8ve","logement frontalier rentr\00E9e","arriver \00E0 Gen\00E8ve septembre"],"image_url":null,"is_generated":false,"blog_post_id":null,"created_at":"2026-07-31T13:47:22.002586+00:00","updated_at":"2026-09-30T07:43:18.866905+00:00"}'::json) r WHERE c.id = r.id;
UPDATE blog_calendar c SET week_number = r.week_number, scheduled_date = r.scheduled_date, title_fr = r.title_fr, title_en = r.title_en, category = r.category, target_audience = r.target_audience, key_points = r.key_points, seo_keywords = r.seo_keywords, image_url = r.image_url, is_generated = r.is_generated, blog_post_id = r.blog_post_id, updated_at = r.updated_at FROM json_populate_record(null::blog_calendar, U&'{"id":"01639a79-6bca-4f00-8f01-a7883ab299b9","week_number":null,"scheduled_date":"2026-12-01","title_fr":"Mutation \00E0 Gen\00E8ve en janvier : trouver ton logement avant d''arriver","title_en":"Relocating to Geneva in January: secure your housing before you arrive","category":"tips","target_audience":"Salari\00E9s mut\00E9s \00E0 Gen\00E8ve au 1er janvier, expats en relocation","key_points":["Pic des mutations de janvier : anticiper d\00E8s d\00E9cembre","Recherche \00E0 distance : ce qui marche, ce qui \00E9choue","R\00E9server une chambre avant d''arriver (process La Villa \00E0 distance)","Checklist arriv\00E9e janvier (permis, assurance, transport)","CTA liste prioritaire + candidature"],"seo_keywords":["mutation Gen\00E8ve janvier","relocation Gen\00E8ve logement","trouver logement avant d''arriver Gen\00E8ve"],"image_url":null,"is_generated":false,"blog_post_id":null,"created_at":"2026-07-31T13:47:22.002586+00:00","updated_at":"2026-07-31T13:47:22.002586+00:00"}'::json) r WHERE c.id = r.id;
DO $c$
DECLARE bad text;
BEGIN
  SELECT string_agg(e.id, ', ') INTO bad FROM (VALUES
    ('64a6d0e7-e04c-442a-a74f-61aaefb634e8','27deb779dec8ada8f9b2118be2506d8a'),
    ('27da94d1-47fb-4f76-a447-60a28173e529','f63310f00e6170971496e4d697273b96'),
    ('01639a79-6bca-4f00-8f01-a7883ab299b9','644391043d44c1c32562821fd91421b0'),
    ('e99838b4-15a9-496a-a2c0-ec5389a02684','2379b452da304a0d4bd281d1dceca2da')) AS e(id, m)
  LEFT JOIN blog_calendar c ON c.id::text = e.id
  WHERE c.id IS NULL OR md5(row_to_json(c)::text) <> e.m;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'retour arriere non conforme : %', bad; END IF;
END $c$;
COMMIT;
